// n8n's Code sandbox does not expose the browser URL global.
function parseSourceUrl(value) {
  const match = String(value || '').trim().match(/^(https?):\/\/([^\/?#\s]+)(\/[^?#\s]*)?(\?[^#\s]*)?(#[^\s]*)?$/i);
  if (!match || match[2].includes('@')) throw new Error('Invalid public source URL');
  const authority = match[2].toLowerCase();
  const parts = authority.match(/^([a-z0-9.-]+)(?::(\d+))?$/i);
  if (!parts) throw new Error('Invalid source host');
  return {
    protocol: match[1].toLowerCase() + ':', hostname: parts[1], port: parts[2] || '',
    pathname: match[3] || '/', search: match[4] || '', hash: match[5] || '',
    toString() { return this.protocol + '//' + this.hostname + (this.port ? ':' + this.port : '') + this.pathname + this.search + this.hash; }
  };
}

const items = $input.all();

function normalizeUrl(value) {
  try {
    const u = parseSourceUrl(String(value || '').trim());
    u.hash = '';
    u.search = '';
    u.hostname = u.hostname.toLowerCase();
    u.pathname = u.pathname.replace(/\/+$/, '') || '/';
    return u.toString();
  } catch {
    return String(value || '').trim().replace(/[?#].*$/, '').replace(/\/+$/, '');
  }
}
function hostOf(value) {
  try { return parseSourceUrl(String(value || '')).hostname.replace(/^www\./,'').toLowerCase(); }
  catch { return ''; }
}
function categoriesOf(item) {
  const c = item.json.categories ?? item.json.category ?? [];
  return (Array.isArray(c) ? c : [c]).map(x => String(x || '').toLowerCase()).join(' ');
}
function hintFor(item) {
  const link = String(item.json.link || '');
  const host = hostOf(link);
  const path = (() => { try { return parseSourceUrl(link).pathname.toLowerCase(); } catch { return ''; }})();
  const cats = categoriesOf(item);

  if (host.includes('espn.com') || path.startsWith('/sport/') || path.startsWith('/sports/')) return 'Sports';
  if (host.includes('techcrunch.com') || host.includes('theverge.com') || host.includes('arstechnica.com')) return 'Technology';
  if (host.includes('nasa.gov') || host.includes('sciencedaily.com') || /science|environment/.test(cats)) return 'Science';
  if (host.includes('fbi.gov') || /crime|policing|criminal/.test(cats) || path.includes('/crime/')) return 'Crime';
  if (host.includes('cnbc.com') || host.includes('fortune.com') || /business|markets|economy|finance/.test(cats)) return 'Business';
  if (host.includes('animenewsnetwork.com')) return 'Anime';
  if (host.includes('ign.com') || host.includes('polygon.com') || host.includes('gamesindustry.biz')) return 'Gaming';
  if (host.includes('variety.com') || host.includes('deadline.com') || path.startsWith('/film/') || /film|television|tv/.test(cats)) return 'Film & TV';
  if (/culture|arts|music|books|theatre/.test(cats)) return 'Culture';
  return 'World';
}

const blocked = [
  /\/video\//i,
  /\/liveblog\//i,
  /\/audio\//i,
  /\/podcast/i
];

items.sort((a,b) => new Date(b.json.isoDate || b.json.pubDate || 0) - new Date(a.json.isoDate || a.json.pubDate || 0));

const seenUrls = new Set();
const candidates = [];
function pickLink(json) {
  const atomLink = json?.['atom:link'];
  const atomHref =
    Array.isArray(atomLink) ? atomLink.find(x => x && typeof x === 'object' && x.href)?.href :
    atomLink && typeof atomLink === 'object' ? atomLink.href :
    '';

  const candidates = [
    json?.link,
    json?.url,
    json?.permalink,
    json?.guid,
    json?.id,
    atomHref
  ];

  for (const value of candidates) {
    const s = String(value || '').trim();
    if (/^https?:\/\//i.test(s)) return s;
  }
  return '';
}

for (const item of items) {
  const link = pickLink(item.json);
  if (!link || blocked.some(re => re.test(link))) continue;

  // Normalize downstream shape so every later node can safely read item.json.link.
  item.json.link = link;

  const key = normalizeUrl(link);
  if (!key || seenUrls.has(key)) continue;
  seenUrls.add(key);
  item.json._sourceHost = hostOf(link);
  item.json._sectionHint = hintFor(item);
  candidates.push(item);
}

// First pass: favor both source-domain and section diversity.
const selected = [];
const usedHosts = new Set();
const usedSections = new Set();
for (const item of candidates) {
  const host = item.json._sourceHost;
  const section = item.json._sectionHint;
  if (usedHosts.has(host) || usedSections.has(section)) continue;
  selected.push(item);
  usedHosts.add(host);
  usedSections.add(section);
  if (selected.length >= 3) break;
}

// Second pass: fill remaining slots with unique domains, even if section repeats.
if (selected.length < 3) {
  for (const item of candidates) {
    if (selected.includes(item)) continue;
    const host = item.json._sourceHost;
    if (usedHosts.has(host)) continue;
    selected.push(item);
    usedHosts.add(host);
    if (selected.length >= 3) break;
  }
}

return selected.slice(0, 3);

const extracted = $json;
