const sourceKey = normalizeSource(source.sourceLink);
const exactSourceMatch = recent.some(x =>
  Array.isArray(x.sourceUrls) && x.sourceUrls.some(url => normalizeSource(url) === sourceKey)
);

return [{
  json:{
    ...source,
    normalizedSourceLink: sourceKey,
    recentTitles:recent.map(x=>x.title).filter(Boolean).slice(0,40),
    exactSourceMatch
  }
}];

