    svg=svg.replace(/viewBox\s*=\s*["'][^"']+["']/i,'viewBox="0 0 1200 675"');
  }else{
    svg=svg.replace(/<svg\b/i,'<svg viewBox="0 0 1200 675"');
  }
  svg=svg.replace(/\swidth\s*=\s*["'][^"']+["']/i,'').replace(/\sheight\s*=\s*["'][^"']+["']/i,'');

  const imagePath=`/generated/ai/${article.slug}.svg`;
  const imageAlt=fallbackAlt(article);
  let markdown=String(article.markdown||'');
  markdown=setFrontmatter(markdown,'image',yamlQuote(imagePath));
  markdown=setFrontmatter(markdown,'imageAlt',yamlQuote(imageAlt));

  result={
    ...article,
    markdown,
    image:imagePath,
    imageAlt,
    aiImageReady:true,
    aiSvg:svg,
    aiSvgBase64:Buffer.from(svg,'utf8').toString('base64'),
    imageGenerationMode:'gemini-svg'
  };
}catch(e){
  result={...result,aiImageError:e.message};
}
return {json:result};

